"use client";

/* eslint-disable @typescript-eslint/no-explicit-any */
// Export all Field components from shadcn with ShadcnField prefix
import type { Control, FieldPath, FieldValues } from "react-hook-form";
import React from "react";
import { Controller } from "react-hook-form";

import type { ColProps } from "../../grid";
import type { FormLabelAlign, FormLayout } from "../types";
import type { Rule } from "../utils";
import { useFormContext } from "../context";
import { buildFieldChildProps } from "../field-binding";
import { useRequiredFieldCheck } from "../hooks/use-field-optionality-check";
import { FormItemRow } from "./form-item-row";

type FormItemProps<TFieldValues extends FieldValues = FieldValues> = {
  // `control` is only used to infer TFieldValues for `name`; it is ignored at
  // runtime. Accept any TContext/TTransformedValues so forms backed by zod
  // schemas with `.default()` (input type ≠ output type) still type-check.
  control?: Control<TFieldValues, any, any>;

  name?: FieldPath<TFieldValues>;
  label?: React.ReactNode;
  description?: React.ReactNode;
  children?: React.ReactElement<{
    onBlur?: (event: any) => void;
    onChange?: (event: any) => void;
    [key: string]: any;
  }>;

  required?: boolean;

  className?: string;
  layout?: FormLayout;
  colon?: boolean;
  labelCol?: ColProps;
  labelAlign?: FormLabelAlign;
  labelWrap?: boolean;
  wrapperCol?: ColProps;

  valuePropName?: string;
  getValueProps?: (value: any) => Record<string, any>;
  normalize?: (value: any, prevValue: any) => any;

  rules?: Rule[];
};
const FormItem = <TFieldValues extends FieldValues = FieldValues>({
  control: _control, // definded for name
  name,
  label,
  description,
  children,
  required: defaultRequired,

  className,
  layout,
  colon,
  labelCol,
  labelAlign,
  labelWrap,
  wrapperCol,

  valuePropName,
  getValueProps,
  normalize,
}: FormItemProps<TFieldValues>) => {
  const formContext = useFormContext();

  const id = formContext?.id;
  const form = formContext?.form;
  const required = useRequiredFieldCheck(name, defaultRequired);

  const mergedLayout = layout ?? formContext?.layout;
  const mergedLabelCol = labelCol ?? formContext?.labelCol;
  const mergedLabelAlign = labelAlign ?? formContext?.labelAlign;
  const mergedLabelWrap = labelWrap ?? formContext?.labelWrap;
  const mergedWrapperCol = wrapperCol ?? formContext?.wrapperCol;
  const mergedColon = colon ?? formContext?.colon;

  if (!name || !form) {
    return (
      <FormItemRow
        id={id}
        name={name}
        label={label}
        description={description}
        required={required}
        className={className}
        layout={mergedLayout}
        colon={mergedColon}
        labelCol={mergedLabelCol}
        labelAlign={mergedLabelAlign}
        labelWrap={mergedLabelWrap}
        wrapperCol={mergedWrapperCol}
        invalid={false}
        errors={[]}
      >
        {children &&
          React.cloneElement(children, {
            id: `${id}-${name}`,
            name,
            "aria-invalid": false,
          })}
      </FormItemRow>
    );
  }

  return (
    <Controller
      control={form.control}
      name={name}
      render={({ field, fieldState }) => {
        return (
          <FormItemRow
            id={id}
            name={name}
            label={label}
            description={description}
            required={required}
            className={className}
            layout={mergedLayout}
            colon={mergedColon}
            labelCol={mergedLabelCol}
            labelAlign={mergedLabelAlign}
            labelWrap={mergedLabelWrap}
            wrapperCol={mergedWrapperCol}
            invalid={fieldState.invalid}
            errors={[fieldState.error]}
          >
            {children &&
              React.cloneElement(
                children,
                buildFieldChildProps({
                  field,
                  id: `${id}-${name}`,
                  name,
                  invalid: fieldState.invalid,
                  valuePropName,
                  getValueProps,
                  normalize,
                  childProps: children.props,
                }),
              )}
          </FormItemRow>
        );
      }}
    />
  );
};

export { FormItem };

import { Children, isValidElement } from "react";

import { cn } from "@acme/ui/lib/utils";
import {
  FormControl as ShadFormControl,
  useFormField,
} from "@acme/ui/shadcn/form";

import type { GenericSlotProps } from "../../slot";
import { AutoComplete } from "../../auto-complete";
import { DatePicker } from "../../date-picker";
import { Select } from "../../select";
import { GenericSlot } from "../../slot";
import { TimePicker } from "../../time-picker";

// import { useFormField } from "../hooks/use-form-field";

const FormControl = ({ className, ...props }: GenericSlotProps) => {
  const { error } = useFormField();

  return (
    <GenericSlot status={error ? "error" : "default"}>
      <ShadFormControl
        className={cn(
          Children.toArray(props.children).some(
            (child) =>
              isValidElement(child) &&
              (child.type === DatePicker ||
                child.type === TimePicker ||
                child.type === Select ||
                child.type === AutoComplete),
          )
            ? "w-full"
            : "",

          className,
        )}
        {...props}
      />
    </GenericSlot>
  );
};

export { FormControl };

import { cn } from "@acme/ui/lib/utils";
import { FieldError, Field as ShadcnField } from "@acme/ui/shadcn/field";

import type { ColProps } from "../../grid";
import type { FormLabelAlign, FormLayout } from "../types";
import { FieldDescription, FieldLabel } from "../../field";
import { Col, Row } from "../../grid";

const FormItemRow = ({
  id,
  name,
  invalid,
  required,
  label,
  description,
  className,
  layout,
  colon,
  labelCol,
  labelAlign,
  labelWrap,
  wrapperCol,
  errors,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  id?: string;
  name?: string;

  invalid?: boolean;

  required?: boolean;

  label?: React.ReactNode;
  description?: React.ReactNode;

  className?: string;
  layout?: FormLayout;
  colon?: boolean;
  labelCol?: ColProps;
  labelAlign?: FormLabelAlign;
  labelWrap?: boolean;
  wrapperCol?: ColProps;

  errors?: Array<{ message?: string } | undefined>;
}) => {
  const formLabelNodes = [
    label ? (
      <FieldLabel
        key="form-item-label"
        htmlFor={id ? `${id}-${name}` : undefined}
        required={required}
        colon={colon}
        className={cn(layout === "horizontal" && "h-control")}
      >
        {label}
      </FieldLabel>
    ) : null,
  ];

  const formControlNodes = [
    children ? (
      <div
        key="form-item-control-input"
        data-slot="form-item-control-input"
        className={cn(
          "min-h-control flex items-center",
          layout === "vertical" && "*:w-full",
        )}
      >
        {children}
      </div>
    ) : null,
    description ? (
      <FieldDescription key="form-item-description">
        {description}
      </FieldDescription>
    ) : null,
    invalid ? (
      <div
        key="form-item-additional"
        data-slot="form-item-additional"
        className="min-h-6 leading-[22px]"
      >
        <FieldError errors={errors} />
      </div>
    ) : null,
  ];

  return (
    <ShadcnField
      data-slot="form-item"
      data-invalid={invalid}
      className={cn(
        invalid ? "mb-0" : "mb-6",
        "gap-x-3 gap-y-1",
        layout === "vertical" ? "flex-col" : "flex-row",
        className,
      )}
      orientation={layout}
      {...props}
    >
      {labelCol || labelAlign || labelWrap || wrapperCol ? (
        <Row
          data-slot="form-item-row"
          className={cn(
            "gap-y-1",
            layout === "vertical" ? "flex-col" : "flex-row",
          )}
        >
          {label ? (
            <Col
              className={cn(
                "pr-3 text-end",
                layout === "vertical" && "text-start",
                labelAlign === "left" && "text-left",
                labelAlign === "right" && "text-right",
                labelWrap === false &&
                  "overflow-hidden text-ellipsis whitespace-nowrap",
              )}
              {...labelCol}
            >
              {formLabelNodes}
            </Col>
          ) : null}
          <Col
            className={cn(
              "flex-1",
              !label && layout !== "vertical" && "ml-auto",
            )}
            style={{
              width: label ? undefined : "100%",
            }}
            offset={label ? undefined : 8}
            {...wrapperCol}
          >
            {formControlNodes}
          </Col>
        </Row>
      ) : null}
      {!labelCol && !labelAlign && !labelWrap && !wrapperCol
        ? formLabelNodes
        : null}
      {!labelCol && !labelAlign && !labelWrap && !wrapperCol
        ? formControlNodes
        : null}
    </ShadcnField>
  );
};

export { FormItemRow };

"use client";

import type * as React from "react";

import { cn } from "@acme/ui/lib/utils";
import { FormLabel as ShadFormLabel } from "@acme/ui/shadcn/form";

import type { ColProps } from "../../grid";
import type { FormLabelAlign, FormLayout } from "../types";
import { Col } from "../../grid";
import { Label } from "../../label";
import { useFormContext } from "../context";

type FormItemLabelProps = React.ComponentProps<typeof ShadFormLabel> & {
  layout?: FormLayout;
  label?: React.ReactNode;
  labelAlign?: FormLabelAlign;
  labelCol?: ColProps;

  required?: boolean;
};

const FormLabel = ({
  className,
  layout = "vertical",
  labelAlign,
  labelCol,
  required,
  children,
  asChild,
  ...props
}: FormItemLabelProps) => {
  const formContext = useFormContext();
  const mergedLabelCol = labelCol ?? formContext?.labelCol;
  const mergedLabelAlign = labelAlign ?? formContext?.labelAlign;
  const labelWrap = formContext?.labelWrap;

  const labelNode = (
    <Label required={required} asChild={asChild}>
      {children}
    </Label>
  );

  return (
    <ShadFormLabel
      className={cn(
        // layout === "vertical" ? "pb-2" : "",
        layout === "horizontal" && !mergedLabelCol ? "h-control w-6/24" : "",
        // Label alignment
        mergedLabelAlign === "left" && "text-left",
        mergedLabelAlign === "right" && "text-right",
        // Label wrap
        labelWrap === false &&
          "overflow-hidden text-ellipsis whitespace-nowrap",
        className,
      )}
      asChild
      {...props}
    >
      {labelCol ? <Col {...labelCol}>{labelNode}</Col> : labelNode}
    </ShadFormLabel>
  );
};

export type { FormItemLabelProps };
export { FormLabel as FieldLabel, FormLabel };

