"use client";

import type { ReactElement } from "react";
import type {
  Control,
  FieldArray,
  FieldArrayPath,
  FieldValues,
  UseFieldArrayReturn,
} from "react-hook-form";
import { useFieldArray } from "react-hook-form";

import { Field } from "../../field";
import { useRequiredFieldCheck } from "../hooks/use-field-optionality-check";

type FieldListProps<
  TFieldValues extends FieldValues = FieldValues,
  TFieldArrayName extends FieldArrayPath<TFieldValues> =
    FieldArrayPath<TFieldValues>,
> = {
  // TContext/TTransformedValues left open so `form.control` from a zod schema
  // with `.default()`/`.optional()` (TTransformedValues ≠ TFieldValues) is accepted.
  control?: Control<TFieldValues, any, any>;
  name: TFieldArrayName;
  label?: string;
  description?: string;
  required?: boolean;
  children?: (
    fields: {
      id: string;
      key: string;
      name: string;
    }[],
    ctx: Omit<
      UseFieldArrayReturn<TFieldValues, TFieldArrayName, "id">,
      "fields" | "remove"
    > & {
      add: (
        defaultValue?:
          | FieldArray<TFieldValues, TFieldArrayName>
          | FieldArray<TFieldValues, TFieldArrayName>[],
        insertIndex?: number,
      ) => void;
      remove: (fieldName: string) => void;
      move: (from: number, to: number) => void;
    },
  ) => ReactElement<any>;
};
const FieldList = <
  TFieldValues extends FieldValues = FieldValues,
  TFieldArrayName extends FieldArrayPath<TFieldValues> =
    FieldArrayPath<TFieldValues>,
>({
  control,
  name,
  label,
  description,
  required,
  children,
}: FieldListProps<TFieldValues, TFieldArrayName>) => {
  const { fields: defaultValues, ...helper } = useFieldArray<
    TFieldValues,
    TFieldArrayName
  >({
    control,
    name,
  });
  const fields = defaultValues.map((value, index) => {
    return {
      id: value.id,
      key: value.id,
      name: `${name}.${index}`,
    };
  });

  const add = (
    defaultValue?:
      | FieldArray<TFieldValues, TFieldArrayName>
      | FieldArray<TFieldValues, TFieldArrayName>[],
    insertIndex?: number,
  ) => {
    if (typeof insertIndex === "number") {
      helper.insert(insertIndex, defaultValue ?? ({} as any));
    } else {
      helper.append(defaultValue ?? ({} as any));
    }
  };

  const remove = (fieldName: string) => {
    const index = fields.findIndex((field) => field.name === fieldName);
    if (index === -1) return;
    helper.remove(index);
  };
  const move = (from: number, to: number) => {
    if (from < 0 || from >= fields.length || to < 0 || to >= fields.length) {
      return;
    }
    helper.move(from, to);
  };

  const ctx = {
    ...helper,
    add,
    remove,
    move,
    errors: control?._formState.errors[name],
  };

  const isOptional = useRequiredFieldCheck(name);

  return (
    <Field
      label={label}
      description={description}
      required={required ?? (isOptional === undefined ? false : !isOptional)}
    >
      {children?.(fields, ctx)}
    </Field>
  );
};

export { FieldList };
export type { FieldListProps as FieldArrayProps };

import { useEffect } from "react";
import { z } from "zod";

import { notification } from "../../notification";
import { useFormContext } from "../context";

export const FormErrorsNotification = () => {
  const formContext = useFormContext();
  const formSchema = formContext?.form?.schema;
  const formFields = formContext?.form?.control._fields;
  const formErrors = formContext?.form?.formState.errors;
  useEffect(() => {
    if (
      formErrors &&
      formSchema &&
      formSchema instanceof z.ZodObject &&
      formFields
    ) {
      // Get the required fields from Zod schema
      const requiredFields = Object.keys(formSchema.shape).filter((key) => {
        const field = formSchema.shape[key];
        return !(field instanceof z.ZodOptional);
      });
      // Get mounted fields from React Hook Form
      const mountedFields = Object.keys(formFields);
      // Get required fields that are not mounted
      const unmountedRequiredFields = new Set(
        requiredFields.filter((field) => !mountedFields.includes(field)),
      );
      // handle show notification
      if (Object.keys(formErrors).length > 0) {
        const unmountedErrorsToNotify = Object.keys(formErrors)
          .filter((key) => {
            return unmountedRequiredFields.has(key);
          })
          .map((key) => {
            return {
              path: key,
              message: formErrors[key]?.message,
            };
          });
        if (unmountedErrorsToNotify.length > 0) {
          notification.error({
            message: "Unexpected Form Errors",
            description: unmountedErrorsToNotify.map((error) => {
              const message =
                typeof error.message === "string" ? error.message : "";
              return `${error.path}: ${message}`;
            }),
            duration: Infinity,
            closeButton: true,
          });
        }
      }
    }
  }, [formErrors, formFields, formSchema]);

  return <></>;
  //   return (
  //     <>
  //       {Object.keys(formErrors || {}).length > 0 && (
